SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.drug, d.route, s.score_range, s.los, s.mortality_percentage, s.readmission_percentage_30_days FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd dc ON a.subject_id = dc.subject_id JOIN (SELECT subject_id, COUNT(*) AS medication_count, SUM(CASE WHEN route IS NOT NULL THEN 1 ELSE 0 END) AS distinct_route_count FROM emar WHERE event_txt = 'Medication' AND charttime <= '2020-01-01' GROUP BY subject_id) AS m ON a.subject_id = m.subject_id JOIN (SELECT subject_id, hadm_id, score_range, los, mortality_percentage, readmission_percentage_30_days FROM icustays WHERE first_careunit = 'INT' AND intime <= '2020-01-01' AND outtime >= '2020-12-31') AS s ON a.subject_id = s.subject_id AND a.hadm_id = s.hadm_id WHERE p.gender = 'F' AND p.anchor_age BETWEEN 87 AND 97 AND dc.icd_code = '391.9' AND m.medication_count > 1 AND m.distinct_route_count > 1 AND s.score_range IS NOT NULL AND s.los IS NOT NULL AND s.mortality_percentage IS NOT NULL AND s.readmission_percentage_30_days IS NOT NULL ORDER BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.drug, d.route, s.score_range, s.los, s.mortality_percentage, s.readmission_percentage_30_days NULLS LAST;